GET http://127.0.0.1:9000/correlation-rules/combined/rules/v1?limit=500&offset=0
< HTTP 200 OK
< body:
{
  "meta": {
    "pagination": {
      "limit": 500,
      "offset": 0,
      "total": 4
    }
  },
  "resources": [
    {
      "id": "ver-1",
      "name": "Okta - Repeated failed logins",
      "rule_id": "rule-okta-brute",
      "search": {
        "filter": "#Vendor=\"okta\" #event.module=\"sso\" event.action=\"user.session.start\" #event.outcome=\"failure\"\n| groupBy([user.name], function=count(as=failures))\n| failures >= 5"
      },
      "severity": 50,
      "state": "published",
      "status": "active",
      "tactic": "Credential Access",
      "technique": "Brute Force",
      "version": 2
    },
    {
      "id": "ver-0",
      "name": "Okta - Repeated failed logins (old)",
      "rule_id": "rule-okta-brute",
      "search": {
        "filter": "#Vendor=\"okta\" event.action=\"anything\""
      },
      "severity": 50,
      "state": "draft",
      "status": "active",
      "version": 1
    },
    {
      "id": "ver-2",
      "name": "AWS - Console login without MFA",
      "rule_id": "rule-aws-nomfa",
      "search": {
        "filter": "#Vendor=\"aws\" #event.module=\"cloudtrail\" event.action=\"ConsoleLogin\"\n| Vendor.additionalEventData.MFAUsed=\"No\" Vendor.responseElements.ConsoleLogin=\"Success\""
      },
      "severity": 70,
      "state": "published",
      "status": "active",
      "tactic": "Initial Access",
      "technique": "Valid Accounts",
      "version": 1
    },
    {
      "id": "ver-3",
      "name": "Entra ID - MFA denied",
      "rule_id": "rule-entra-mfa",
      "search": {
        "filter": "#Vendor = microsoft AND @sourcetype = \"microsoft-entra-id\" AND #event.outcome != success\n| Vendor.properties.status.additionalDetails = \"MFA denied*\""
      },
      "severity": 40,
      "state": "published",
      "status": "inactive",
      "version": 1
    }
  ]
}

