< HTTP 200 OK
< body:
{
  "resources": [
    {
      "id": "tpl-pp",
      "name": "Proofpoint - Malicious message delivered",
      "search": {
        "filter": "#Vendor=\"proofpoint\" Vendor.threatsInfoMap[0].classification=/malware|phish/i Vendor.threatsInfoMap[0].threatStatus=\"active\""
      },
      "severity": 70
    },
    {
      "id": "tpl-ftnt",
      "name": "Fortinet - Allowed traffic to unexpected country",
      "search": {
        "filter": "#Vendor=fortinet Vendor.action=\"accept\" | !in(field=Vendor.dstcountry, values=[\"United States\", \"Reserved\"])"
      },
      "severity": 40
    },
    {
      "id": "tpl-okta-admin",
      "name": "Okta - Admin role granted",
      "search": {
        "filter": "#Vendor=\"okta\" event.action=\"user.account.privilege.grant\""
      },
      "severity": 60
    },
    {
      "id": "tpl-edr",
      "name": "Endpoint - Encoded PowerShell",
      "search": {
        "filter": "#event_simpleName=ProcessRollup2 CommandLine=/-enc/i"
      },
      "severity": 70
    }
  ]
}

